.global-info-section{
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    width: 100%;
    height: 100%;
    min-height: 266px;
    overflow: hidden;
    position: relative;
    background-color: #F5F5F5;
}

.global-info-section
    .text-container{
        display: flex;
        flex-direction: column;
        justify-content: center;
        align-items: center;
        width: 100%;
        gap: 12px;
        max-width: 980px;
        padding: 50px 0;
        z-index: 1;
        text-align: center;
}

.global-info-section
    .text-container
        .title{
            display: inline;
            font-family: 'pitanga-regular';
            font-size: 24px;
}

.global-info-section
    .text-container
        .text{
            display: inline;
            font-size: 16px;
            font-family: 'oxygen-regular';
}
.global-info-section
    .text-container
        .link{
            font-size: 16px;
            font-family: 'oxygen-regular';
            font-weight: 600;
            color: #0435AC;
}

body:not(.has-edit-mode-menu) 
.global-info-section
    .text-container
        .link::after{
            content: '>';
            font-size: 16px;
            font-family: 'oxygen-regular';
            font-weight: 600;
            color: #0435AC;
            margin-left: 4px;
}

@media (min-width:580px) and (max-width: 1000px){
    .global-info-section 
        .text-container {
            padding: 46px 46px 77px;
            gap: 18px;
    }
}

@media (max-width:580px){
    .global-info-section 
        .text-container {
            padding: 46px 14px 65px;
            gap: 20px;
    }
}

