css:
footer .portlet-body{
	background-color: transparent !important;
}

footer{
	background-color: #2C2C2C;
	color: white !important;
	font-family: "oxygen-regular";
}

footer .redes-sociais{
	padding: 32px 0;
	background-color: #051C65;
	width: 100%;
}

footer .redes-sociais.azul-claro{
	background-color: #0435ac;
}

footer .redes-sociais .container{
	justify-content: space-between;
}

footer .redes-sociais img{
	margin-left: 32px;
	width: 35px;
}

footer .principal{
	padding: 40px 0;
}

footer .container{
	display: flex;
	flex-wrap: wrap;
}

footer .coluna-1{
	padding: 0;
}

footer .coluna-1 .info{
	font-size: 14px;
	margin-top: 20px;
	line-height: 26px;
}

footer .coluna-1 .ans{
    display: flex;
    margin-bottom: 18px;
}

footer .coluna-1 .ans .selo-ans{
    width: 126px;
    margin-right: 15px;
}

footer .coluna-1 .ans .selos{
    display: flex;
    justify-content: space-between;
    flex-direction: column;
}

footer .coluna-1 .ans .selos img.um-selo{
	display: none;
}

footer .coluna-1 .ans .selos img{
    width: 86px;
}

footer .coluna-1 .cookies{
	background-color: #000 !important;
    color: #FFFFFF;
    font-size: 12px;
    border: 1px solid #FFFFFF;
    font-weight: bold;
    padding: 4px !important;
}

footer .coluna-2{
	display:flex;
	padding: 0 100px;
}

footer .coluna-2 .portlet{
	width: 100%;
}

footer .coluna-2 .portlet .portlet-header {
    margin-bottom: 0;
}

footer .coluna-2 .footer-menu{
	display: flex;
	width: 100%;
}

footer .coluna-2 .footer-menu .internal-column{
	margin-left: 35px;
}

footer .coluna-2 .footer-menu span a{
	font-size: 16px;
	font-family: "oxygen-bold";
	margin-bottom: 23px;
	color: white;
}

footer .coluna-2 .footer-menu .submenu-container{
	display: flex;
	flex-direction: column;
	margin-top: 23px;
}

footer .coluna-2 .footer-menu .submenu-link{
	text-decoration: underline;
	margin-bottom: 19px;
	color: white;
    font-size: 14px;
}

footer .coluna-3{
	display: flex;
	flex-direction: column;
	padding: 0;
}

footer .coluna-3 .apps{
	margin-top: 22px;
}

footer .coluna-3 .apps.buttons-row{
	display: flex;
}

footer .coluna-3 .apps.buttons-row img:first-child{
	margin-right: 25px;
}

footer .coluna-3 span{
	font-family: "oxygen-bold";
	font-size: 18px;
	margin-bottom: 22px;
}

footer .coluna-3 img{
	width: 133px;
	margin-bottom: 20px;
}

footer .coluna-3 .selo-ans{
	width: 148px;
	margin-bottom: 24px;
}

footer .copy-right{
	padding: 10px 0;
	display: flex;
	justify-content: center;
	align-items: center;
	background-color: black;
	font-family: "oxygen-regular";
	font-size: 14px;
}

footer .copy-right-interno.inside{
	display: flex;
}

footer .copy-right-interno.inside span{
	font-size: 14px;
	font-family: 'oxygen-regular';
}

footer .copy-right-interno{
	display: none;
}

footer .copy-right.inside{
	display: none;
}

@media (min-width: 1200px) {
    footer .container {
        max-width: 1241px;
    }
}

@media (max-width: 1201px) {
    footer .coluna-1 .ans{
        flex-direction: column;
    }

    footer .coluna-1 .ans .selo-ans{
        margin-bottom: 15px;
    }

	footer .coluna-2{
		padding: 0 50px;
	}
}

@media (max-width: 991px) {
    footer .coluna-1{
        margin-top: -100px;
        order: 2;
    }

    footer .coluna-2{
        order: 2;
    }

	footer .coluna-2 .footer-menu .col-12:first-child{
		padding-right: 15px;
	}

	footer .coluna-2 .footer-menu .col-12:nth-child(2){
		padding-left: 15px;
	}
	footer .coluna-3{
		flex-direction: row-reverse;
		justify-content: end;
		flex-wrap: wrap;
        order: 1;
	}

	footer .coluna-3 .app-container{
		margin-left: 94px;
	}

	footer .coluna-3 .apps{
		flex-direction: row;
	}

	footer .coluna-3 .apps img:first-child{
		margin-right: 20px;
	}

	footer .container {
		max-width: 790px;
	}
}
@media (max-width: 768px) {
	footer .redes-sociais img{
		margin-left: 0;
		margin-right: 12px;
		width: 32px;
	}

	footer .coluna-2 {
		padding: 0;
	}


	footer .container {
		max-width: 714px;
	}

}

@media (max-width: 575px) {
    footer .redes-sociais .container{
		display: flex;
		flex-direction: column;
	}

	footer .redes-sociais span{
		margin-bottom: 15px;
	}

	footer .principal{
		padding: 30px 0;
	}

	footer .container{
		display: flex;
		flex-direction: column-reverse;
	}

	footer .coluna-1{
		order: 1;
        margin-top: 0;
        border-top: 1px solid white;
        padding-top: 22px;
	}

	footer .coluna-2{
		order: 2;
		padding: 0;
        border-top: 1px solid white;
        padding-top: 22px;
	}

    footer .coluna-2 .footer-menu{
        flex-direction: column;
    }

    footer .coluna-2 .footer-menu .internal-column {
        margin-left: 0;
    }

	footer .coluna-2 .footer-menu .col-12:first-child{
		padding-right: 0;
		margin-bottom: 20px;
	}

	footer .coluna-2 .footer-menu .col-12:nth-child(2){
		padding-left: 0;
	}

	footer .coluna-3{
		order: 3;
        justify-content: start;
	}

	footer .coluna-3 span{
		margin-bottom: 16px;
	}

	footer .coluna-3 .app-container {
        margin-left: 0;
    }

	footer .coluna-3 .apps{
		margin-bottom: 30px;
	}

	footer .coluna-3 .apps img:first-child{
		margin-right: 12px;
	}

	footer .copy-right{
		font-size: 8px;
	}
}

.component-html img {
	max-width: 100%;
}

.submenu-outros-portais {
	display: none;
}

body.has-control-menu .acessibilidade_header {
	top: 56px;
}

.acessibilidade_header {
	background-color: #EFEEE7;
	position: fixed;
	width: 100%;
	top: 0;
	z-index: 900;
	padding: 3px 0;
}

/* itens internos */
.acessibilidade_header div {
	display: inline-block;
	border-right: 2px solid rgba(128, 128, 128, 0.24);
	padding: 0 12px;
	text-align: right;
	min-height: 35px;
	color: rgba(76, 71, 71, 0.86);
	vertical-align: middle;
	font-family: "oxygen-bold";
	font-size: 15px;
	cursor: pointer;
}

.acessibilidade_header div a {
	color: rgba(76, 71, 71, 0.86);
	text-decoration: none;
}

#outros-portais svg {
  transition: transform 0.3s ease;
}

.accessibility-button{
	display: inline-flex;
    width: fit-content;
    align-items: center;
    gap: 7px;
    background: transparent;
    padding: 7px 20px;
    border: 0;
    color: #2C2C2C;
    font-family: 'oxygen-regular';
    font-size: 12px;
    font-style: normal;
    font-weight: 700;
	vertical-align: middle;
}

