	content: url('data:image/svg+xml,%3Csvg%20width%3D%2218%22%20height%3D%2220%22%20fill%3D%22none%22%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%3E%3Cpath%20d%3D%22M9%204a2%202%200%201%201%200-4%202%202%200%200%201%200%204Z%22%20fill%3D%22%232D2D2D%22%2F%3E%3Cpath%20d%3D%22m16.616%204.032-.02.005-.018.005a5.218%205.218%200%200%200-.13.036c-.805.218-4.713%201.236-7.467%201.236-2.558%200-6.113-.88-7.25-1.178a3.385%203.385%200%200%200-.346-.104C.563%203.832%200%204.604%200%205.31c0%20.699.68%201.032%201.365%201.27v.012l4.12%201.19c.422.148.534.3.589.433.179.423.036%201.262-.015%201.555l-.25%201.8-1.394%207.048-.011.058-.01.051c-.1.646.413%201.273%201.384%201.273.849%200%201.223-.541%201.385-1.278%200%200%201.212-6.302%201.818-6.302.605%200%201.853%206.302%201.853%206.302.162.737.537%201.278%201.385%201.278.974%200%201.488-.63%201.385-1.278a2.13%202.13%200%200%200-.033-.162l-1.412-6.99-.25-1.8c-.182-1.048-.036-1.394.013-1.475a.047.047%200%200%200%20.004-.006c.046-.08.26-.26.756-.432l3.863-1.248a.779.779%200%200%200%20.07-.021C17.308%206.348%2018%206.016%2018%205.311s-.562-1.479-1.384-1.28Z%22%20fill%3D%22%232D2D2D%22%2F%3E%3C%2Fsvg%3E');
	display: inline-block;
