/* responsivo */
@media (max-width: 991px) {
	.acessibilidade_header {
		padding-left: 35px;
		text-align: center;
	}

	.item_desk {
		display: none !important;
	}
}

@media (min-width: 992px) {
	.acessibilidade_header {
		text-align: right;
	}

	.item_desk {
		display: inline-block !important;
	}
}

/* Sienna */

.asw-menu-btn {
    display: none !important;
    visibility: hidden !important;
    opacity: 0 !important;
    pointer-events: none !important;
}

.asw-menu-content > .asw-card:first-child {
    display: none !important;
}

.sienna-shortcut-info {
	display: flex !important;
	align-items: center !important;
	gap: 7px !important;
	width: 100% !important;
	min-height: 50px !important;
	padding: 12px 24px !important;
	margin: 0 !important;
	background: #ffffff !important;
	border-bottom: 1px solid #e5e7eb !important;
	color: #111827 !important;
	font-family: inherit !important;
	font-size: 12px !important;
	font-weight: 600 !important;
	line-height: 1.2 !important;
	box-sizing: border-box !important;
	flex-shrink: 0 !important;
}

.sienna-shortcut-info__label {
	display: inline-flex !important;
	align-items: center !important;
	color: #111827 !important;
	font-size: 12px !important;
	font-weight: 600 !important;
	line-height: 1.2 !important;
	white-space: nowrap !important;
}

.sienna-shortcut-info__key {
	display: inline-flex !important;
	align-items: center !important;
	justify-content: center !important;
	min-width: 25px !important;
	height: 22px !important;
	padding: 0 7px !important;
	border: 1px solid #9bb8f5 !important;
	border-radius: 5px !important;
	background: #edf4ff !important;
	color: #003c96 !important;
	font-family: inherit !important;
	font-size: 11px !important;
	font-weight: 700 !important;
	line-height: 1 !important;
	text-transform: uppercase !important;
	box-shadow: inset 0 -1px 0 rgba(0, 60, 150, 0.15) !important;
}

.sienna-shortcut-info__plus {
	display: inline-flex !important;
	align-items: center !important;
	color: #111827 !important;
	font-size: 13px !important;
	font-weight: 700 !important;
	line-height: 1 !important;
}

