.global-section-card {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 100%;
  overflow: hidden;
  position: relative;
  gap: 16px;
  z-index: 2;
}

.global-section-card .section-card-title {
  font-size: 24px;
  line-height: 40px;
  font-family: 'oxygen-bold';
  color: var(--black);
  width: 100%;
  text-align: center;
}

.global-section-card .section-card-text {
  font-size: 16px;
  line-height: 33px;
  font-family: 'oxygen-regular';
  color: var(--dark);
  width: 100%;
  text-align: center;
}

.global-section-card-container img {
  display: block;
  width: 100%;
  height: 100%;
  z-index: 1;
  right: 0;
  position: absolute;
  top: 0;
}

/* Spacing */

.global-section-card-container.banner-small {
  padding: 4rem 0;
}

.global-section-card-container.banner-medium {
  padding: 5rem 0;
}

.global-section-card-container.banner-large {
  padding: 6rem 0;
}

.global-section-card-container.banner-larger {
  padding: 7rem 0;
}

.global-section-card-container.banner-huge {
  padding: 8rem 0;
}

.global-section-card-container.banner-gigantic {
  padding: 9rem 0;
}

/* Button */
.global-section-card .editable-button {
  display: inline-block;
  width: fit-content;
  height: fit-content;
  border-radius: 7px;
  padding: 14px 18px;
  font-family: "oxygen-bold";
  text-decoration: none;
  border: 1px solid transparent;
  transition: all .2s ease-in-out;
  text-align: center;
}

.global-section-card .editable-button.primary {
  background: var(--primary);
  color: var(--white);
  font-size: 20px;
  line-height: 20px;
}

.global-section-card .editable-button.primary-outline {
  border: 1px solid var(--primary);
  color: var(--primary);
  background: var(--white);
  font-size: 16px;
  line-height: 20px;
  padding: 10px 60px;
}

.global-section-card .editable-button.primary-white-background {
  background: var(--white);
  color: var(--primary);
  font-size: 20px;
  line-height: 20px;
}

.global-section-card .editable-button.primary:hover {
    background: var(--white);
    border: 1px solid var(--primary);
    color: var(--primary);
}

.global-section-card .editable-button.primary-outline:hover {
  color: var(--lighter);
  background-color: var(--primary);
}

.global-section-card .editable-button.primary-white-background:hover {
  opacity: 0.8;
}

.global-section-card .editable-button.secondary {
  background: var(--secondary);
  color: var(--white);
  font-size: 20px;
  line-height: 20px;
}

.global-section-card .editable-button.secondary-outline {
  border: 1px solid var(--secondary);
  color: var(--secondary);
  background: var(--white);
  font-size: 20px;
  line-height: 20px;
}

.global-section-card .editable-button.secondary-white-background {
  background: var(--white);
  color: var(--secondary);
  font-size: 20px;
  line-height: 20px;
}

.global-section-card .editable-button.secondary:hover {
  opacity: 0.8;
}

.global-section-card .editable-button.secondary-outline:hover {
  color: var(--lighter);
  background-color: var(--secondary);
}

.global-section-card .editable-button.secondary-white-background:hover {
  opacity: 0.8;
}

/* Color */

.global-section-card .primary {
  color: var(--primary);
}

.global-section-card .secondary {
  color: var(--secondary);
}

.global-section-card .tele-linear-1 {
  color: var(--tele-linear-1);
}

.global-section-card .tele-linear-2 {
  color: var(--tele-linear-2);
}

.global-section-card .chat-linear-1 {
  color: var(--chat-linear-1);
}

.global-section-card .chat-linear-2 {
  color: var(--chat-linear-2);
}

.global-section-card .success {
  color: var(--success);
}

.global-section-card .info {
  color: var(--info);
}

.global-section-card .warning {
  color: var(--warning);
}

.global-section-card .danger {
  color: var(--danger);
}

.global-section-card .gray-dark {
  color: var(--gray-dark);
}

.global-section-card .dark {
  color: var(--dark);
}

.global-section-card .light {
  color: var(--light);
}

.global-section-card .lighter {
  color: var(--lighter);
}

.global-section-card .white {
  color: var(--white);
}

.global-section-card .black {
  color: var(--black);
}

