const flowBar = document.getElementById("flow-bar");

if (flowBar && !document.body.classList.contains("has-edit-mode-menu")) {
	const behavior = flowBar.classList.contains("fixedBottom")
		? "fixedBottom"
		: "scrollTop";

	if (behavior === "fixedBottom") {
		flowBar.style.position = "fixed";
		flowBar.style.left = "0";
		flowBar.style.right = "0";
		flowBar.style.bottom = "0";
		flowBar.style.top = "auto";
		flowBar.style.zIndex = "98";
		flowBar.style.transform = "none";

		document.body.style.paddingBottom = `${flowBar.offsetHeight}px`;
	}

	if (behavior === "scrollTop") {
		const initialOffsetTop = flowBar.offsetTop;
		let lastScrollY = window.scrollY;

		if (window.innerWidth > 1200) {
			window.addEventListener("scroll", () => {
				const offset = document.body.classList.contains("has-control-menu") ? 193 : 137;
				const currentScrollY = window.scrollY;
				const scrollingDown = currentScrollY > lastScrollY;
				const atTop = currentScrollY <= 0;

				if (atTop) {
					flowBar.style.position = "relative";
					flowBar.style.top = "initial";
					flowBar.style.bottom = "auto";
					flowBar.style.zIndex = "initial";
					flowBar.style.transition = "transform 0.3s ease-in-out";
					flowBar.style.transform = "translateY(0)";
				} else if (scrollingDown && currentScrollY >= initialOffsetTop) {
					flowBar.style.position = "fixed";
					flowBar.style.top = "0";
					flowBar.style.bottom = "auto";
					flowBar.style.zIndex = "98";
					flowBar.style.transition = "transform 0.3s ease-in-out";
					flowBar.style.transform = `translateY(${offset}px)`;
				}

				lastScrollY = currentScrollY;
			});
		}
	}

	const buttons = flowBar.querySelectorAll(".bar-button");

	function openBannerGroup(groupNumber) {
		setTimeout(() => {
			const banner = document.querySelector(".global-banner-dinamic-intern-pages");
			if (!banner) return;

			const container = banner.querySelector(".buttons-container");
			const button = banner.querySelector(`#button-${groupNumber}`);
			const group = banner.querySelector(`#group-${groupNumber}`);

			if (!container || !button || !group) return;

			banner.querySelectorAll("#group-1, #group-2").forEach((gp) => {
				gp.classList.remove("active");
			});

			banner.querySelectorAll("#button-1, #button-2").forEach((btn) => {
				btn.classList.remove("active");
			});

			button.classList.add("active");
			group.classList.add("active");
			container.classList.add("group-open");

			const offset = document.body.classList.contains("has-control-menu") ? 193 : 137;
			const targetTop = banner.getBoundingClientRect().top + window.scrollY - offset;

			window.scrollTo({
				top: targetTop,
				behavior: "smooth"
			});
		}, 0);
	}

	buttons.forEach((button) => {
		button.addEventListener("click", (event) => {
			const href = button.getAttribute("href");

			if (!href) return;

			if (href === "#pessoa-fisica") {
				event.preventDefault();
				event.stopPropagation();

				openBannerGroup(1);
				return;
			}

			if (href === "#pessoa-juridica") {
				event.preventDefault();
				event.stopPropagation();

				openBannerGroup(2);
				return;
			}

			if (!href.startsWith("#")) return;

			event.preventDefault();

			window.scrollTo({
				top: 0,
				behavior: "smooth"
			});
		});
	});
};

