.oypu-cardsQualiServicos{
position: relative;
}
.oypu-cardsQualiServicos .slick-list{
display:flex;
	width: 100%;
}
.oypu-cardsQualiServicos .slick-track{
display:flex;
/*column-gap: 30px;*/
	width:100%;
}
		.oypu-cardsQualiServicos .slick-track .oypu-blocoQuali + .oypu-blocoQuali{
	 margin-left:30px!important;
	}
.oypu-cardsQualiServicos .slick-slide{
height:auto;
}
.oypu-cardsQualiServicos .oypu-blocoQualiTexto {
display: flex;
flex-direction: column;
height: 100%;
}

.oypu-cardsQualiServicos .oypu-arrow_prevQuali span, .oypu-cardsQualiServicos .oypu-arrow_nextQuali span{
display: inline-block;
width: 30px;
height: 30px;
line-height:26px;
background-color: #2D2D2D;
overflow:hidden;
cursor: pointer;
}

.oypu-cardsQualiServicos .oypu-sliderQualiServicos .oypu-blocoQuali{
background: #FFFFFF 0% 0% no-repeat padding-box;
box-shadow: 0px 3px 6px #0000004A;
border-radius: 3px;
min-height: 191px;
width:100%;
}

/*Custom slick*/
.oypu-cardsQualiServicos .oypu-arrow_prevQuali, .oypu-cardsQualiServicos .oypu-arrow_nextQuali {
position: absolute;
bottom: 50%;
border: none;
background: transparent;
height:30px;
padding:2px;
}
.oypu-cardsQualiServicos button:focus-visible, .oypu-cardsQualiServicos button:focus-visible{
outline: auto!important;
}
.oypu-cardsQualiServicos button:focus{
outline-width: medium;
outline-style: none;
outline-color: invert;
}
.oypu-cardsQualiServicos .oypu-arrow_nextQuali {
right: -3%;
}
.oypu-cardsQualiServicos .oypu-arrow_prevQuali{
right: initial;
left: -3%;
}

.oypu-cardsQualiServicos .oypu-sliderQualiServicos .slick-dots li button:before{
font-size: 12px;
}
.oypu-cardsQualiServicos .oypu-sliderQualiServicos .slick-dots li.slick-active button:before{
color:#0054B8;
font-size: 12px;
background-color: var(--primary)!important;
border-radius: 2px;
opacity:1;
}

.oypu-cardsQualiServicos .oypu-arrow_prevQuali.slick-arrow.slick-disabled, .oypu-cardsQualiServicos .oypu-arrow_nextQuali.slick-arrow.slick-disabled{
opacity:0.25;
}
.oypu-cardsQualiServicos .oypu-arrow_prevQuali,
.oypu-cardsQualiServicos .oypu-arrow_nextQuali {
display: none;
}

.oypu-cardsQualiServicos .oypu-sliderQualiServicos .slick-dots li button:before{
border: 1px solid var(--primary)!important;
content:"";
border-radius: 2px;
width: 10px;
height: 10px;
}
.oypu-cardsQualiServicos .oypu-sliderQualiServicos .slick-dots li button:hover:before, .oypu-cardsQualiServicos .oypu-sliderQualiServicos .slick-dots li button:focus:before{
color:initial;
}

.oypu-cardsQualiServicos .oypu-sliderQualiServicos .slick-dots{
display:flex;
justify-content: end;
}
.oypu-cardsQualiServicos .oypu-sliderQualiServicos .slick-dots li{
 margin:0!important;
}
.oypu-cardsQualiServicos .oypu-sliderQualiServicos .oypu-blocoQuali .oypu-blocoQualiTexto a.oypu-btnCard{
min-width: 167px;
display:flex;
align-items: center;
justify-content: center;
text-align:center;
color:#fff;
height: 43px;
background: #223AA9;
margin-top:auto;
}
.oypu-cardsQualiServicos .oypu-sliderQualiServicos .oypu-blocoQuali .oypu-blocoQualiTexto a.oypu-btnCard:hover{
