const fragmentContainer = fragmentElement.querySelector('.global-card-link-grid');

const cards = fragmentContainer.querySelectorAll("div[id^='card-']");

cards.forEach(card => {
  const cardId = card.id;
  const span = card.querySelector(`span.link#${cardId}`);

  let href = "";
  let target = "_self";

  if (span) {
    const innerLink = span.querySelector("a");

    if (innerLink) {
      const innerHref = innerLink.getAttribute("href");
      href = innerHref === "#" ? "" : innerHref || "";
      target = innerLink.getAttribute("target") || "_self";

      span.textContent = innerLink.textContent;
    }

    span.removeAttribute("href");
    span.removeAttribute("target");
  }

  const anchor = document.createElement("a");
  anchor.id = cardId;
  anchor.className = card.className;

  if (href) anchor.href = href;
  if (target) anchor.target = target;

  while (card.firstChild) {
    anchor.appendChild(card.firstChild);
  }

  card.parentNode.replaceChild(anchor, card);
});;

